func arSources(cg *port.Cells, g int32) int32 {
	var s int32 = 0
	if player.CgGet(cg, g, player.CgfTcount()) > 0 {
		s += model.SrText()
	}
	if player.CgGet(cg, g, player.CgfHcount()) > 0 {
		s += model.SrHiddenText()
	}
	if player.CgGet(cg, g, player.CgfOcount()) > 0 {
		s += model.SrOcr()
	}
	return s
}

func arDecide(g int32, cg *port.Cells, refs *port.Cells, ofw *port.Cells, etext *port.Cells, feats *port.Cells, owords *port.Cells, images *port.Cells, epages *port.Cells, gv *port.Cells, gd *port.Cells, fx *port.Cells, afa *port.Cells) int32 {
	// Decide group g: fill its columns, take the first rule that holds, record the verdict in `gd`, the columns the rule read in
	// `fx`, and a dropped ghost in `afa`.
	var r int32 = fuserules.FrDecide(gv)
	var base int32 = g * 10
	var win int32 = fuserules.FrWinner(r)
	var flags int32 = fuserules.FrFlags(r)
	var conf int32 = fuserules.FrConf(r)
	var k int32 = 0
	var col int32 = 0
	var sc int32 = 0
	var o0 int32 = 0
	var orow int32 = 0
	var gfl int32 = 0
	var fa int32 = 0
	if conf < 0 {
		sc = port.CellsAt(gv, fuserules.AgScore())
		conf = 500
		if sc >= 0 {
			conf = sc
			if conf > 900 {
				conf = 900
			}
		}
	}
	// a verdict for the text layer in a group that has none is the default's: OCR, low confidence
	if (win == fuserules.FwText()) && ((port.CellsAt(gv, fuserules.AgNt()) == 0) && (port.CellsAt(gv, fuserules.AgNh()) == 0)) {
		win = fuserules.FwOcr()
		flags |= model.FlOcrOnly()
	}
	port.CellsSet(gd, base, r)
	port.CellsSet(gd, base+1, fuserules.FrNumber(r))
	port.CellsSet(gd, base+2, win)
	port.CellsSet(gd, base+3, conf)
	port.CellsSet(gd, base+4, flags)
	port.CellsSet(gd, base+5, fuserules.FrReason(r))
	port.CellsSet(gd, base+6, 0)
	port.CellsSet(gd, base+7, arSources(cg, g))
	// the explanation: every column the deciding rule read, and the value it read
	for k < fuserules.FrNpred() {
		col = fuserules.FrPcol(r, k)
		if col >= 0 {
			player.FxNew(fx, g, fuserules.FrNumber(r), col, port.CellsAt(gv, col))
		}
		k += 1
	}
	// held in a figure: the group says so (a seal's group is held by its own row, 128, and says so in its flag already)
	gfl = player.CgGet(cg, g, player.CgfFlags())
	if (win == fuserules.FwNone()) && ((fuserules.FrReason(r) == 0) && ((flags & 128) == 0)) {
		player.CgSet(cg, g, player.CgfFlags(), gfl|player.PlgInFigure())
	}
	// set aside from the hidden layer (P7.6; no OCR word in the group, not a defence's row): one row a hidden word, its text range in cells 8 and 11
	if (win == fuserules.FwNone()) && ((fuserules.FrReason(r) > 0) && ((fuserules.FrDefence(r) == 0) && (player.CgGet(cg, g, player.CgfOcount()) == 0))) {
		k = 0
		for k < player.CgGet(cg, g, player.CgfHcount()) {
			orow = arRef(refs, player.CgGet(cg, g, player.CgfHfirst())+k, 1)
			fa = player.FaNew(afa, player.CgGet(cg, g, player.CgfPage()), port.CellsAt(ofw, (orow*24)+1), port.CellsAt(ofw, (orow*24)+2), port.CellsAt(ofw, (orow*24)+3), port.CellsAt(ofw, (orow*24)+4), fuserules.FrReason(r), evidence.EaWords(), orow)
			player.FaSet(afa, fa, 8, port.CellsAt(ofw, (orow*24)+11))
			player.FaSet(afa, fa, 11, port.CellsAt(ofw, (orow*24)+12))
			player.FaSet(afa, fa, 9, g)
			player.FaSet(afa, fa, 10, fuserules.FrNumber(r))
			k += 1
		}
	}
	// dropped as a ghost (plausibility: defence 6 of SPEC 9.5, whichever the core row): the first OCR word's box stands for the group in the set-aside list
	if (win == fuserules.FwNone()) && ((fuserules.FrReason(r) > 0) && ((fuserules.FrDefence(r) == 0) && (player.CgGet(cg, g, player.CgfOcount()) > 0))) {
		o0 = player.CgGet(cg, g, player.CgfOfirst())
		orow = arRef(refs, o0, 1)
		fa = player.FaNew(afa, player.CgGet(cg, g, player.CgfPage()), player.CgGet(cg, g, player.CgfX0()), player.CgGet(cg, g, player.CgfY0()), player.CgGet(cg, g, player.CgfX1()), player.CgGet(cg, g, player.CgfY1()), fuserules.FrReason(r), evidence.EaOwords(), orow)
		player.FaSet(afa, fa, 8, 6)
		player.FaSet(afa, fa, 9, g)
		player.FaSet(afa, fa, 10, fuserules.FrNumber(r))
	}
	// P7.5, dropped by a defence: an OCR-only group's every OCR word is a row (a watermark is a phrase), the rule's defence in column 8; a text-layer
	// group's every visible word is a row whose subject is its text (the OCR words aligned to it go with it, not listed again)
	if (win == fuserules.FwNone()) && ((fuserules.FrReason(r) > 0) && (fuserules.FrDefence(r) > 0)) {
		if player.CgGet(cg, g, player.CgfTcount()) > 0 {
			k = 0
			for k < player.CgGet(cg, g, player.CgfTcount()) {
				o0 = arRef(refs, player.CgGet(cg, g, player.CgfTfirst())+k, 1)
				fa = player.FaNew(afa, port.CellsAt(ofw, o0*24), port.CellsAt(ofw, (o0*24)+1), port.CellsAt(ofw, (o0*24)+2), port.CellsAt(ofw, (o0*24)+3), port.CellsAt(ofw, (o0*24)+4), fuserules.FrReason(r), evidence.EaEtext(), port.CellsAt(ofw, (o0*24)+11))
				player.FaSet(afa, fa, 8, fuserules.FrDefence(r))
				player.FaSet(afa, fa, 9, g)
				player.FaSet(afa, fa, 10, fuserules.FrNumber(r))
				player.FaSet(afa, fa, 11, port.CellsAt(ofw, (o0*24)+12))
				k += 1
			}
		} else {
			k = 0
			for k < player.CgGet(cg, g, player.CgfOcount()) {
				orow = arRef(refs, player.CgGet(cg, g, player.CgfOfirst())+k, 1)
				fa = player.FaNew(afa, evidence.OwGet(owords, orow, evidence.HdPage()), evidence.OwGet(owords, orow, evidence.HdX0()), evidence.OwGet(owords, orow, evidence.HdY0()), evidence.OwGet(owords, orow, evidence.HdX1()), evidence.OwGet(owords, orow, evidence.HdY1()), fuserules.FrReason(r), evidence.EaOwords(), orow)
				player.FaSet(afa, fa, 8, fuserules.FrDefence(r))
				player.FaSet(afa, fa, 9, g)
				player.FaSet(afa, fa, 10, fuserules.FrNumber(r))
				k += 1
			}
		}
	}
	return 0
}

func arRemeasure(nfl *port.Cells, nfw *port.Cells, l int32, first int32, cnt int32) int32 {
	// Line l of `nfl` measured again from its words (a run of `nfw`): the union of their boxes, the baseline from the first
	// word's start to the last word's end (as `th-run` does for a line that lost a word).
	var x0 int32 = port.CellsAt(nfw, (first*24)+1)
	var y0 int32 = port.CellsAt(nfw, (first*24)+2)
	var x1 int32 = port.CellsAt(nfw, (first*24)+3)
	var y1 int32 = port.CellsAt(nfw, (first*24)+4)
	var i int32 = 1
	var v int32 = 0
	var lastw int32 = first + (cnt - 1)
	for i < cnt {
		v = port.CellsAt(nfw, ((first+i)*24)+1)
		if v < x0 {
			x0 = v
		}
		v = port.CellsAt(nfw, ((first+i)*24)+2)
		if v < y0 {
			y0 = v
		}
		v = port.CellsAt(nfw, ((first+i)*24)+3)
		if v > x1 {
			x1 = v
		}
		v = port.CellsAt(nfw, ((first+i)*24)+4)
		if v > y1 {
			y1 = v
		}
		i += 1
	}
	port.CellsSet(nfl, (l*16)+1, x0)
	port.CellsSet(nfl, (l*16)+2, y0)
	port.CellsSet(nfl, (l*16)+3, x1)
	port.CellsSet(nfl, (l*16)+4, y1)
	// the baseline keeps the line's own heights (a hidden layer's words carry baselines of their own, a sixth of a point apart, and a line
	// re-measured from them would tilt: P7.6); only its ends move to the first and last word's
	v = port.CellsAt(nfw, (first*24)+5)
	port.CellsSet(nfl, (l*16)+5, v)
	v = port.CellsAt(nfw, (lastw*24)+7)
	port.CellsSet(nfl, (l*16)+7, v)
	return 0
}

func arPutFv(fv *port.Cells, g int32, source int32, number int32, conf int32, flags int32) int32 {
	player.FvNew(fv, g, source, number, conf, flags)
	return 0
}

func arCopyWord(nfw *port.Cells, ofw *port.Cells, w int32, lrow int32, src int32) int32 {
	// Copy word w of the old flow into the new one, on line `lrow`, with its `src` cell set; answers its row.
	var r int32 = player.FwCopyWord(nfw, ofw, w, lrow)
	port.CellsSet(nfw, (r*24)+evidence.WfSrc(), src)
	return r
}

func arEmitOcr(g int32, cg *port.Cells, refs *port.Cells, ofw *port.Cells, etext *port.Cells, owords *port.Cells, nfw *port.Cells, fv *port.Cells, gd *port.Cells, lrow int32) int32 {
	// The OCR words of group g, in place of its text-layer words (see the head of this file), appended to `nfw` on line `lrow`.
	var nt int32 = player.CgGet(cg, g, player.CgfTcount())
	var nh int32 = player.CgGet(cg, g, player.CgfHcount())
	var no int32 = player.CgGet(cg, g, player.CgfOcount())
	var of int32 = player.CgGet(cg, g, player.CgfOfirst())
	var base int32 = g * 10
	var number int32 = port.CellsAt(gd, base+1)
	var conf int32 = port.CellsAt(gd, base+3)
	var flags int32 = port.CellsAt(gd, base+4)
	var srcs int32 = port.CellsAt(gd, base+7)
	var tf int32 = player.CgGet(cg, g, player.CgfTfirst())
	var nrep int32 = nt
	var j int32 = 0
	var orow int32 = 0
	var t0 int32 = 0
	var tj int32 = 0
	var tl int32 = 0
	var r int32 = 0
	var ux0 int32 = 0
	var uy0 int32 = 0
	var ux1 int32 = 0
	var uy1 int32 = 0
	var v int32 = 0
	var bx0 int32 = 0
	var bx1 int32 = 0
	var by0 int32 = 0
	var k int32 = 0
	var rot int32 = 0
	var orot int32 = 0
	if nt == 0 {
		tf = player.CgGet(cg, g, player.CgfHfirst())
		nrep = nh
	}
	t0 = arRef(refs, tf, 1)
	tl = arRef(refs, tf+(nrep-1), 1)
	// the union of the replaced words' boxes
	ux0 = port.CellsAt(ofw, (t0*24)+1)
	uy0 = port.CellsAt(ofw, (t0*24)+2)
	ux1 = port.CellsAt(ofw, (t0*24)+3)
	uy1 = port.CellsAt(ofw, (t0*24)+4)
	k = 1
	for k < nrep {
		tj = arRef(refs, tf+k, 1)
		v = port.CellsAt(ofw, (tj*24)+1)
		if v < ux0 {
			ux0 = v
		}
		v = port.CellsAt(ofw, (tj*24)+2)
		if v < uy0 {
			uy0 = v
		}
		v = port.CellsAt(ofw, (tj*24)+3)
		if v > ux1 {
			ux1 = v
		}
		v = port.CellsAt(ofw, (tj*24)+4)
		if v > uy1 {
			uy1 = v
		}
		k += 1
	}
	rot = port.CellsAt(ofw, (t0*24)+9)
	for j < no {
		orow = arRef(refs, of+j, 1)
		if nrep == no {
			tj = arRef(refs, tf+j, 1)
		} else {
			tj = t0
		}
		r = player.FwCopyWord(nfw, ofw, tj, lrow)
		port.CellsSet(nfw, (r*24)+11, evidence.OwGet(owords, orow, evidence.HdTstart()))
		port.CellsSet(nfw, (r*24)+12, evidence.OwGet(owords, orow, evidence.HdTlen()))
		port.CellsSet(nfw, (r*24)+14, evidence.OwGet(owords, orow, evidence.HdConf()))
		port.CellsSet(nfw, (r*24)+15, -1)
		// a visible word's replacement has no glyph run (no glyph says this word); a hidden word's keeps it, so the style stage still reads its fill (P7.6)
		if nt > 0 {
			port.CellsSet(nfw, (r*24)+17, -1)
			port.CellsSet(nfw, (r*24)+18, 0)
		}
		port.CellsSet(nfw, (r*24)+23, srcs)
		if nrep != no {
			orot = evidence.OwGet(owords, orow, 9)
			// an unrotated line: OCR's extent along it, the text layer's band across it and its baseline
			if (rot == 0) && (orot == 0) {
				bx0 = evidence.OwGet(owords, orow, evidence.HdX0())
				bx1 = evidence.OwGet(owords, orow, evidence.HdX1())
				by0 = port.CellsAt(ofw, (t0*24)+6)
				port.CellsSet(nfw, (r*24)+1, bx0)
				port.CellsSet(nfw, (r*24)+2, uy0)
				port.CellsSet(nfw, (r*24)+3, bx1)
				port.CellsSet(nfw, (r*24)+4, uy1)
				port.CellsSet(nfw, (r*24)+5, bx0)
				port.CellsSet(nfw, (r*24)+6, by0)
				port.CellsSet(nfw, (r*24)+7, bx1)
				port.CellsSet(nfw, (r*24)+8, by0)
			} else {
				k = 1
				for k < 11 {
					port.CellsSet(nfw, (r*24)+k, evidence.OwGet(owords, orow, k))
					k += 1
				}
			}
			// spacing: a space between the OCR words, the last one ends as the text layer's last word did
			if (j + 1) < no {
				port.CellsSet(nfw, (r*24)+evidence.WfWbreak(), evidence.WbSpace())
				v = evidence.OwGet(owords, arRef(refs, of+(j+1), 1), evidence.HdX0()) - port.CellsAt(nfw, (r*24)+3)
				if v < 0 {
					v = 0
				}
				port.CellsSet(nfw, (r*24)+evidence.WfGap(), v)
			} else {
				v = port.CellsAt(ofw, (tl*24)+evidence.WfWbreak())
				port.CellsSet(nfw, (r*24)+evidence.WfWbreak(), v)
				v = port.CellsAt(ofw, (tl*24)+evidence.WfGap())
				port.CellsSet(nfw, (r*24)+evidence.WfGap(), v)
			}
		}
		arPutFv(fv, g, model.SrOcr(), number, conf, flags)
		j += 1
	}
	return no
}

func arWordSource(ofw *port.Cells, w int32) int32 {
	// The source a word stands for when no group decided it: `ocr` for an OCR line's word, `hidden-text`, else `text`.
	var s int32 = port.CellsAt(ofw, (w*24)+evidence.WfSrc())
	if (s & model.SrOcr()) != 0 {
		return model.SrOcr()
	}
	if (s & model.SrHiddenText()) != 0 {
		return model.SrHiddenText()
	}
	return model.SrText()
}

func arFlushOcrOnly(page int32, cg *port.Cells, refs *port.Cells, etext *port.Cells, owords *port.Cells, olines *port.Cells, oruns *port.Cells, osyms *port.Cells, gd *port.Cells, o2g *port.Cells, nfw *port.Cells, nfl *port.Cells, fv *port.Cells, tw *port.Cells, tl *port.Cells, scr *port.Cells) int32 {
	// The admitted OCR-only words of `page`, each OCR line's own as a line of the fused flow, measured as an OCR line is (D213).
	var nr int32 = evidence.OrCount(oruns)
	var r int32 = 0
	var l0 int32 = 0
	var nl int32 = 0
	var rotmed int32 = 0
	var l int32 = 0
	var tli int32 = 0
	var cnt int32 = 0
	var w0 int32 = 0
	var j int32 = 0
	var orow int32 = 0
	var g int32 = 0
	var twr int32 = 0
	var first int32 = 0
	var kept int32 = 0
	var lrow int32 = 0
	var trow int32 = 0
	var made int32 = 0
	var nrow int32 = 0
	for r < nr {
		if evidence.OrGet(oruns, r, evidence.OrfPage()) == page {
			l0 = evidence.OrGet(oruns, r, evidence.OrfLfirst())
			nl = evidence.OrGet(oruns, r, evidence.OrfLcount())
			rotmed = evidence.EvRotMedian(olines, l0, nl)
			port.CellsDrop(tw, 0)
			port.CellsDrop(tl, 0)
			scan.ScPrep(scr)
			scan.ScEmitLines(olines, owords, osyms, l0, nl, page, rotmed, scr, tw, tl)
			l = l0
			tli = 0
			twr = 0
			for l < (l0 + nl) {
				cnt = evidence.OlGet(olines, l, evidence.LhCount())
				if cnt > 0 {
					w0 = evidence.OlGet(olines, l, evidence.LhFirst())
					first = player.FwCount(nfw)
					lrow = player.FlCount(nfl)
					kept = 0
					j = 0
					for j < cnt {
						orow = w0 + j
						g = port.CellsAt(o2g, orow)
						if g >= 0 {
							if (port.CellsAt(gd, (g*10)+2) == fuserules.FwOcr()) && ((player.CgGet(cg, g, player.CgfTcount()) == 0) && (player.CgGet(cg, g, player.CgfHcount()) == 0)) {
								trow = twr + j
								nrow = player.FwCopyWord(nfw, tw, trow, lrow)
								port.CellsSet(nfw, (nrow*24)+evidence.WfSrc(), port.CellsAt(gd, (g*10)+7))
								player.FvNew(fv, g, model.SrOcr(), port.CellsAt(gd, (g*10)+1), port.CellsAt(gd, (g*10)+3), port.CellsAt(gd, (g*10)+4))
								kept += 1
							}
						}
						j += 1
					}
					if kept > 0 {
						player.FlCopyLine(nfl, tl, tli, first, kept)
						if kept < cnt {
							arRemeasure(nfl, nfw, lrow, first, kept)
						}
						made += 1
					}
					twr += cnt
					tli += 1
				}
				l += 1
			}
		}
		r += 1
	}
	return made
}

func arPageAgreement(cg *port.Cells, g0 int32, g1 int32, refs *port.Cells, ofw *port.Cells, etext *port.Cells) int32 {
	// How far the engine can be trusted on a page (per mille), from the groups [g0, g1) of that page. Of the groups with a visible
	// text-layer candidate and an OCR candidate, the share whose case-folded similarity is at least `agree-sim`, in ANY script (an
	// engine that cannot read the page agrees with nothing); 1000 when fewer than three groups have both. And 0 when 30 per cent or more of
	// the page's text-layer words are in a script the engine lacks (it cannot read what it was not trained on, whatever it says).
	var g int32 = g0
	var both int32 = 0
	var agree int32 = 0
	var k int32 = 0
	var words int32 = 0
	var foreign int32 = 0
	for g < g1 {
		if (player.CgGet(cg, g, player.CgfTcount()) > 0) && ((player.CgGet(cg, g, player.CgfOcount()) > 0) && ((player.CgGet(cg, g, player.CgfFlags()) & player.PlgInSeal()) == 0)) {
			both += 1
			if player.CgGet(cg, g, player.CgfSimfold()) >= health.HhAgreeSim() {
				agree += 1
			}
		}
		k = 0
		for k < player.CgGet(cg, g, player.CgfTcount()) {
			words += 1
			if arWordLatin(ofw, etext, arRef(refs, player.CgGet(cg, g, player.CgfTfirst())+k, 1)) == 0 {
				foreign += 1
			}
			k += 1
		}
		g += 1
	}
	if (words > 0) && ((foreign * 10) >= (words * 3)) {
		return 0
	}
	if both < 3 {
		return 1000
	}
	return (agree * 1000) / both
}

func ArDoc(cg *port.Cells, refs *port.Cells, ofw *port.Cells, ofl *port.Cells, etext *port.Cells, feats *port.Cells, owords *port.Cells, olines *port.Cells, oruns *port.Cells, osyms *port.Cells, images *port.Cells, epages *port.Cells, gl *port.Cells, mk *port.Cells, an *port.Cells, txt *port.Cells, trust int32, rc *port.Cells, nfw *port.Cells, nfl *port.Cells, fv *port.Cells, fx *port.Cells, afa *port.Cells, gd *port.Cells, gv *port.Cells, w2g *port.Cells, o2g *port.Cells, pp *port.Cells, tw *port.Cells, tl *port.Cells, scr *port.Cells) int32 {
	// See the head of this file. The new arenas and the scratch are the caller's (any contents; they are emptied here).
	var ng int32 = player.CgCount(cg)
	var nofw int32 = player.FwCount(ofw)
	var nofl int32 = player.FlCount(ofl)
	var now int32 = evidence.OwCount(owords)
	var i int32 = 0
	var k int32 = 0
	var g int32 = 0
	var l int32 = 0
	var w int32 = 0
	var wend int32 = 0
	var page int32 = 0
	var cur int32 = -1
	var first int32 = 0
	var lrow int32 = 0
	var changed int32 = 0
	var base int32 = 0
	var win int32 = 0
	var r int32 = 0
	var s int32 = 0
	var np int32 = 0
	var pend int32 = 0
	port.CellsDrop(nfw, 0)
	port.CellsDrop(nfl, 0)
	port.CellsDrop(fv, 0)
	port.CellsDrop(fx, 0)
	port.CellsDrop(afa, 0)
	port.CellsDrop(gd, 0)
	port.CellsDrop(gv, 0)
	port.CellsDrop(w2g, 0)
	port.CellsDrop(o2g, 0)
	port.CellsDrop(pp, 0)
	i = 0
	for i < fuserules.AgCount() {
		port.CellsPush(gv, 0)
		i += 1
	}
	i = 0
	for i < nofw {
		port.CellsPush(w2g, -1)
		i += 1
	}
	i = 0
	for i < now {
		port.CellsPush(o2g, -1)
		i += 1
	}
	i = 0
	for i < (ng * 10) {
		port.CellsPush(gd, 0)
		i += 1
	}
	// P7.5 defence 2: the OCR-only groups that recur at the same place on most pages (`rc`, a flag a group)
	artifact.AxRecur(cg, refs, owords, etext, epages, rc, pp)
	port.CellsDrop(pp, 0)
	// the agreement of each group's page with OCR, before any group is decided (a page where the engine and the text layer do not agree
	// is a page whose OCR-only words are not to be admitted)
	g = 0
	for g < ng {
		k = g
		for (k < ng) && (player.CgGet(cg, k, player.CgfPage()) == player.CgGet(cg, g, player.CgfPage())) {
			k += 1
		}
		s = arPageAgreement(cg, g, k, refs, ofw, etext)
		i = g
		for i < k {
			port.CellsSet(gd, (i*10)+8, s)
			i += 1
		}
		g = k
	}
	// the map from a word to its group, and from an OCR word to its group
	g = 0
	for g < ng {
		k = 0
		for k < player.CgGet(cg, g, player.CgfTcount()) {
			r = arRef(refs, player.CgGet(cg, g, player.CgfTfirst())+k, 1)
			port.CellsSet(w2g, r, g)
			k += 1
		}
		k = 0
		for k < player.CgGet(cg, g, player.CgfHcount()) {
			r = arRef(refs, player.CgGet(cg, g, player.CgfHfirst())+k, 1)
			port.CellsSet(w2g, r, g)
			k += 1
		}
		k = 0
		for k < player.CgGet(cg, g, player.CgfOcount()) {
			r = arRef(refs, player.CgGet(cg, g, player.CgfOfirst())+k, 1)
			port.CellsSet(o2g, r, g)
			k += 1
		}
		arFill(g, port.CellsAt(gd, (g*10)+8), cg, refs, ofw, etext, feats, owords, images, epages, gl, mk, an, txt, trust, rc, gv)
		arDecide(g, cg, refs, ofw, etext, feats, owords, images, epages, gv, gd, fx, afa)
		g += 1
	}
	// the pages that have an admitted OCR-only group, ascending (a group's page; `cg` is in page order)
	g = 0
	for g < ng {
		if (port.CellsAt(gd, (g*10)+2) == fuserules.FwOcr()) && ((player.CgGet(cg, g, player.CgfTcount()) == 0) && (player.CgGet(cg, g, player.CgfHcount()) == 0)) {
			page = player.CgGet(cg, g, player.CgfPage())
			if page != cur {
				cur = page
				port.CellsPush(pp, page)
			}
		}
		g += 1
	}
	pend = 0
	cur = -1
	l = 0
	for l < nofl {
		page = port.CellsAt(ofl, l*16)
		if page != cur {
			// the previous page's OCR-only lines, then every pending page before this one
			if cur >= 0 {
				if (pend < port.CellsLen(pp)) && (port.CellsAt(pp, pend) == cur) {
					arFlushOcrOnly(cur, cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr)
					pend += 1
				}
			}
			for (pend < port.CellsLen(pp)) && (port.CellsAt(pp, pend) < page) {
				arFlushOcrOnly(port.CellsAt(pp, pend), cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr)
				pend += 1
			}
			cur = page
		}
		first = player.FwCount(nfw)
		lrow = player.FlCount(nfl)
		changed = 0
		w = port.CellsAt(ofl, (l*16)+11)
		wend = w + port.CellsAt(ofl, (l*16)+12)
		for w < wend {
			g = port.CellsAt(w2g, w)
			if g < 0 {
				s = arWordSource(ofw, w)
				arCopyWord(nfw, ofw, w, lrow, port.CellsAt(ofw, (w*24)+evidence.WfSrc()))
				if s == model.SrOcr() {
					arPutFv(fv, -1, s, 101, 500, model.FlOcrOnly())
				} else {
					arPutFv(fv, -1, s, 101, 900, 0)
				}
			} else {
				base = g * 10
				win = port.CellsAt(gd, base+2)
				if win == fuserules.FwOcr() {
					if port.CellsAt(gd, base+6) == 0 {
						port.CellsSet(gd, base+6, 1)
						arEmitOcr(g, cg, refs, ofw, etext, owords, nfw, fv, gd, lrow)
					}
					changed = 1
				} else if win == fuserules.FwNone() {
					changed = 1
				} else {
					s = arWordSource(ofw, w)
					r = arCopyWord(nfw, ofw, w, lrow, port.CellsAt(ofw, (w*24)+evidence.WfSrc())|port.CellsAt(gd, base+7))
					arPutFv(fv, g, s, port.CellsAt(gd, base+1), port.CellsAt(gd, base+3), port.CellsAt(gd, base+4))
				}
			}
			w += 1
		}
		np = player.FwCount(nfw) - first
		if np > 0 {
			player.FlCopyLine(nfl, ofl, l, first, np)
			if changed == 1 {
				arRemeasure(nfl, nfw, lrow, first, np)
			}
		}
		l += 1
	}
	// the last page's OCR-only lines, and the pages after it
	if (cur >= 0) && ((pend < port.CellsLen(pp)) && (port.CellsAt(pp, pend) == cur)) {
		arFlushOcrOnly(cur, cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr)
		pend += 1
	}
	for pend < port.CellsLen(pp) {
		arFlushOcrOnly(port.CellsAt(pp, pend), cg, refs, etext, owords, olines, oruns, osyms, gd, o2g, nfw, nfl, fv, tw, tl, scr)
		pend += 1
	}
	return ng
}

func arLo(a int32, b int32) int32 {
	if a < b {
		return a
	}
	return b
}

func arHi(a int32, b int32) int32 {
	if a > b {
		return a
	}
	return b
}

func arWriteText(afa *port.Cells, i int32, etext *port.Cells, ledger *port.Cells, text *port.Cells, tmp *port.Cells, tt *port.Cells) int32 {
	// One ledger row for the run of text-layer words (subject `etext`) that starts at row i of `afa`: the words of one page, one reason and one
	// line (a box that overlaps the last one's vertically by at least half the smaller height), joined by a space; confidence 900, src `text`.
	// Answers the row after the run.
	var n int32 = player.FaCount(afa)
	var j int32 = i + 1
	var k int32 = 0
	var s int32 = 0
	var e int32 = 0
	var x0 int32 = player.FaGet(afa, i, 1)
	var y0 int32 = player.FaGet(afa, i, 2)
	var x1 int32 = player.FaGet(afa, i, 3)
	var y1 int32 = player.FaGet(afa, i, 4)
	var ov int32 = 0
	var hs int32 = 0
	var lr int32 = 0
	var t0 int32 = 0
	var more int32 = 1
	for (j < n) && (more == 1) {
		more = 0
		if (player.FaGet(afa, j, 0) == player.FaGet(afa, i, 0)) && ((player.FaGet(afa, j, 5) == player.FaGet(afa, i, 5)) && (player.FaGet(afa, j, 6) == evidence.EaEtext())) {
			ov = arLo(player.FaGet(afa, j, 4), player.FaGet(afa, j-1, 4)) - arHi(player.FaGet(afa, j, 2), player.FaGet(afa, j-1, 2))
			hs = player.FaGet(afa, j, 4) - player.FaGet(afa, j, 2)
			if hs > (player.FaGet(afa, j-1, 4) - player.FaGet(afa, j-1, 2)) {
				hs = player.FaGet(afa, j-1, 4) - player.FaGet(afa, j-1, 2)
			}
			if (hs > 0) && ((ov * 2) >= hs) {
				more = 1
				j += 1
			}
		}
	}
	port.CellsDrop(tt, 0)
	k = i
	for k < j {
		if k > i {
			port.CellsPush(tt, 32)
		}
		if player.FaGet(afa, k, 1) < x0 {
			x0 = player.FaGet(afa, k, 1)
		}
		if player.FaGet(afa, k, 2) < y0 {
			y0 = player.FaGet(afa, k, 2)
		}
		if player.FaGet(afa, k, 3) > x1 {
			x1 = player.FaGet(afa, k, 3)
		}
		if player.FaGet(afa, k, 4) > y1 {
			y1 = player.FaGet(afa, k, 4)
		}
		s = player.FaGet(afa, k, 7)
		e = s + player.FaGet(afa, k, 11)
		for s < e {
			port.CellsPush(tt, port.CellsAt(etext, s))
			s += 1
		}
		k += 1
	}
	lr = model.LedgerAdd(ledger, player.FaGet(afa, i, 5), player.FaGet(afa, i, 0), x0, y0, x1, y1, 900, model.SrText())
	t0 = port.CellsLen(text)
	normalize.NzNfc(tt, 0, port.CellsLen(tt), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
	model.LedgerSetText(ledger, lr, t0, port.CellsLen(text)-t0)
	return j
}

func ArWrite(afa *port.Cells, owords *port.Cells, etext *port.Cells, ledger *port.Cells, text *port.Cells, tmp *port.Cells, tt *port.Cells) int32 {
	// The OCR groups dropped as ghosts (`afa`) as ledger rows, after `fu-write`: a run of rows of one page and one OCR line is ONE row,
	// its box the union of theirs, its text the first words joined by a space (NFC, ligatures folded, as every ledger text), its
	// confidence 700 (an engine's reading of nothing the text layer or the ink explains), src `ocr`. Answers the rows written.
	var n int32 = player.FaCount(afa)
	var i int32 = 0
	var j int32 = 0
	var k int32 = 0
	var s int32 = 0
	var e int32 = 0
	var x0 int32 = 0
	var y0 int32 = 0
	var x1 int32 = 0
	var y1 int32 = 0
	var lr int32 = 0
	var t0 int32 = 0
	var rows int32 = 0
	var line int32 = 0
	var w int32 = 0
	for i < n {
		if player.FaGet(afa, i, 6) == evidence.EaEtext() {
			j = arWriteText(afa, i, etext, ledger, text, tmp, tt)
			rows += 1
			i = j
		} else {
			j = i + 1
			if player.FaGet(afa, i, 6) == evidence.EaWords() {
				// a hidden word set aside (P7.6): a run of rows of one page whose boxes share a line (the next starts above the first's bottom) is one row, `invisible`, src `hidden-text`
				for (j < n) && ((player.FaGet(afa, j, 6) == evidence.EaWords()) && ((player.FaGet(afa, j, 0) == player.FaGet(afa, i, 0)) && (player.FaGet(afa, j, 2) < player.FaGet(afa, i, 4)))) {
					j += 1
				}
				x0 = player.FaGet(afa, i, 1)
				y0 = player.FaGet(afa, i, 2)
				x1 = player.FaGet(afa, i, 3)
				y1 = player.FaGet(afa, i, 4)
				port.CellsDrop(tt, 0)
				k = i
				for k < j {
					if k > i {
						port.CellsPush(tt, 32)
					}
					if player.FaGet(afa, k, 1) < x0 {
						x0 = player.FaGet(afa, k, 1)
					}
					if player.FaGet(afa, k, 2) < y0 {
						y0 = player.FaGet(afa, k, 2)
					}
					if player.FaGet(afa, k, 3) > x1 {
						x1 = player.FaGet(afa, k, 3)
					}
					if player.FaGet(afa, k, 4) > y1 {
						y1 = player.FaGet(afa, k, 4)
					}
					s = player.FaGet(afa, k, 8)
					e = s + player.FaGet(afa, k, 11)
					for s < e {
						port.CellsPush(tt, port.CellsAt(etext, s))
						s += 1
					}
					k += 1
				}
				lr = model.LedgerAdd(ledger, player.FaGet(afa, i, 5), player.FaGet(afa, i, 0), x0, y0, x1, y1, 900, model.SrHiddenText())
				t0 = port.CellsLen(text)
				normalize.NzNfc(tt, 0, port.CellsLen(tt), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
				model.LedgerSetText(ledger, lr, t0, port.CellsLen(text)-t0)
				rows += 1
				i = j
			} else {
				w = player.FaGet(afa, i, 7)
				line = evidence.OwGet(owords, w, evidence.HdLine())
				for (j < n) && ((player.FaGet(afa, j, 6) == evidence.EaOwords()) && ((player.FaGet(afa, j, 0) == player.FaGet(afa, i, 0)) && ((player.FaGet(afa, j, 5) == player.FaGet(afa, i, 5)) && (evidence.OwGet(owords, player.FaGet(afa, j, 7), evidence.HdLine()) == line)))) {
					j += 1
				}
				x0 = player.FaGet(afa, i, 1)
				y0 = player.FaGet(afa, i, 2)
				x1 = player.FaGet(afa, i, 3)
				y1 = player.FaGet(afa, i, 4)
				port.CellsDrop(tt, 0)
				k = i
				for k < j {
					if k > i {
						port.CellsPush(tt, 32)
					}
					if player.FaGet(afa, k, 1) < x0 {
						x0 = player.FaGet(afa, k, 1)
					}
					if player.FaGet(afa, k, 2) < y0 {
						y0 = player.FaGet(afa, k, 2)
					}
					if player.FaGet(afa, k, 3) > x1 {
						x1 = player.FaGet(afa, k, 3)
					}
					if player.FaGet(afa, k, 4) > y1 {
						y1 = player.FaGet(afa, k, 4)
					}
					w = player.FaGet(afa, k, 7)
					s = evidence.OwGet(owords, w, evidence.HdTstart())
					e = s + evidence.OwGet(owords, w, evidence.HdTlen())
					for s < e {
						port.CellsPush(tt, port.CellsAt(etext, s))
						s += 1
					}
					k += 1
				}
				lr = model.LedgerAdd(ledger, player.FaGet(afa, i, 5), player.FaGet(afa, i, 0), x0, y0, x1, y1, 700, model.SrOcr())
				t0 = port.CellsLen(text)
				normalize.NzNfc(tt, 0, port.CellsLen(tt), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
				model.LedgerSetText(ledger, lr, t0, port.CellsLen(text)-t0)
				rows += 1
				i = j
			}
		}
	}
	return rows
}

func arTagApply(nodes *port.Cells, n int32, allocr int32, suspect int32, onlyc int32, lowc int32, conf int32) int32 {
	// Provenance of one node: `ocr` is added to its source (`text` leaves it when every word was OCR's), the flags and the confidence.
	var s int32 = model.NodeSrc(nodes, n)
	if allocr == 1 {
		if (s & model.SrText()) != 0 {
			model.NodeSetSrc(nodes, n, s-model.SrText())
		}
		model.NodeAddSrc(nodes, n, model.SrOcr())
	} else {
		model.NodeAddSrc(nodes, n, model.SrOcr())
	}
	if suspect == 1 {
		model.NodeAddFlag(nodes, n, model.FlTextLayerSuspect())
	}
	if onlyc == 1 {
		model.NodeAddFlag(nodes, n, model.FlOcrOnly())
	}
	if lowc == 1 {
		model.NodeAddFlag(nodes, n, model.FlLowConf())
	}
	if (conf >= 0) && ((model.NodeConf(nodes, n) < 0) || (conf < model.NodeConf(nodes, n))) {
		model.NodeSetConf(nodes, n, conf)
	}
	return 0
}

func ArTag(nodes *port.Cells, regions *port.Cells, nfw *port.Cells, fv *port.Cells) int32 {
	// The Model's provenance, after the paragraphs are built, from the fused flow's verdicts (`fv`, one row a word of `nfw`). A LEAF BLOCK
	// (a block that has an inline child or a text run of its own) is judged by the words whose centre lies in its region on its page: when OCR won any of
	// them its source gets `ocr` (and loses `text` when OCR won all of them), `text-layer-suspect` when OCR replaced a text-layer
	// word, `ocr-only` when OCR won all and one of them was admitted from OCR alone, `low-conf` when a verdict was; its inlines
	// follow, and its confidence is lowered to the mean of the OCR words' when they won all. A block no OCR word touched is not
	// changed: the Model of a page where the text layer won everywhere is the text layer's, byte for byte. (A block is the grain
	// because paragraph building does not carry a word's source into the node; D285.) Answers the blocks tagged.
	var nn int32 = model.NodeCount(nodes)
	var nw int32 = player.FwCount(nfw)
	var n int32 = 1
	var c int32 = 0
	var inl int32 = 0
	var rg int32 = 0
	var page int32 = 0
	var w int32 = 0
	var cx int32 = 0
	var cy int32 = 0
	var total int32 = 0
	var nocr int32 = 0
	var nhid int32 = 0
	var nsus int32 = 0
	var nonly int32 = 0
	var nlow int32 = 0
	var csum int32 = 0
	var any int32 = 0
	var tagged int32 = 0
	var conf int32 = -1
	var allocr int32 = 0
	var suspect int32 = 0
	var onlyc int32 = 0
	var lowc int32 = 0
	w = 0
	for w < nw {
		if port.CellsAt(fv, (w*8)+1) == model.SrOcr() {
			any = 1
		}
		w += 1
	}
	if any == 0 {
		return 0
	}
	for n < nn {
		if (model.NodeIsInline(nodes, n) == 0) && (model.NodeRegionCount(nodes, n) > 0) {
			inl = 0
			c = model.NodeFirstChild(nodes, n)
			for c >= 0 {
				if model.NodeIsInline(nodes, c) == 1 {
					inl = 1
				}
				c = model.NodeNext(nodes, c)
			}
			if model.NodeHasText(nodes, n) == 1 {
				inl = 1
			}
			if inl == 1 {
				total = 0
				nocr = 0
				nhid = 0
				nsus = 0
				nonly = 0
				nlow = 0
				csum = 0
				rg = model.NodeRegionHead(nodes, n)
				for rg >= 0 {
					page = model.RegionPage(regions, rg)
					w = 0
					for w < nw {
						if port.CellsAt(nfw, w*24) == page {
							cx = (port.CellsAt(nfw, (w*24)+1) + port.CellsAt(nfw, (w*24)+3)) / 2
							cy = (port.CellsAt(nfw, (w*24)+2) + port.CellsAt(nfw, (w*24)+4)) / 2
							if (cx >= model.RegionX0(regions, rg)) && ((cx <= model.RegionX1(regions, rg)) && ((cy >= model.RegionY0(regions, rg)) && (cy <= model.RegionY1(regions, rg)))) {
								total += 1
								if port.CellsAt(fv, (w*8)+1) == model.SrOcr() {
									nocr += 1
									if (port.CellsAt(fv, (w*8)+2) >= 300) && (port.CellsAt(fv, (w*8)+2) < 400) {
										nhid += 1
									}
									csum += port.CellsAt(fv, (w*8)+3)
									if (port.CellsAt(fv, (w*8)+4) & model.FlTextLayerSuspect()) != 0 {
										nsus += 1
									}
									if (port.CellsAt(fv, (w*8)+4) & model.FlOcrOnly()) != 0 {
										nonly += 1
									}
									if (port.CellsAt(fv, (w*8)+4) & model.FlLowConf()) != 0 {
										nlow += 1
									}
								} else if (port.CellsAt(fv, (w*8)+4) & model.FlLowConf()) != 0 {
									nlow += 1
								}
							}
						}
						w += 1
					}
					rg = model.RegionNext(regions, rg)
				}
				if nocr > 0 {
					allocr = 0
					conf = -1
					if nocr == total {
						allocr = 1
						conf = csum / nocr
						// words a hidden layer's rows (block 300) gave to OCR keep the layer's box and line: the block stays `text` too (P7.6)
						if nhid == nocr {
							allocr = 2
						}
					}
					suspect = 0
					if nsus > 0 {
						suspect = 1
					}
					onlyc = 0
					if (allocr == 1) && (nonly > 0) {
						onlyc = 1
					}
					lowc = 0
					if nlow > 0 {
						lowc = 1
					}
					arTagApply(nodes, n, allocr, suspect, onlyc, lowc, conf)
					c = model.NodeFirstChild(nodes, n)
					for c >= 0 {
						if model.NodeIsInline(nodes, c) == 1 {
							arTagApply(nodes, c, allocr, suspect, onlyc, lowc, conf)
						}
						c = model.NodeNext(nodes, c)
					}
					tagged += 1
				}
			}
		}
		n += 1
	}
	return tagged
}
